2	
3	import com.example.starter.epidemic.api.CardResponse;
4	import com.example.starter.epidemic.api.ReviewRequest;
5	import com.example.starter.epidemic.api.SubmitCardRequest;
6	import com.example.starter.epidemic.api.WithdrawRequest;
7	import com.example.starter.epidemic.domain.CardStatus;
8	import com.example.starter.epidemic.service.ApiException;
9	import com.example.starter.epidemic.service.EpidemicCardService;
10	import org.junit.jupiter.api.Test;
11	import org.springframework.beans.factory.annotation.Autowired;
12	
13	import java.util.ArrayList;
14	import java.util.List;
15	import java.util.concurrent.CyclicBarrier;
16	import java.util.concurrent.ExecutorService;
17	import java.util.concurrent.Executors;
18	import java.util.concurrent.Future;
19	import java.util.concurrent.TimeUnit;
20	import java.util.concurrent.atomic.AtomicReference;
21	
22	import static org.junit.jupiter.api.Assertions.assertEquals;
23	import static org.junit.jupiter.api.Assertions.assertTrue;
24	
25	/**
26	 * H2 真实并发测试：初审通过与撤回并发时必须形成唯一终态；并发重复报告由唯一约束裁决只建一张卡。
27	 */
28	class ConcurrencyTest extends AbstractIntegrationTest {
29	
30	    @Autowired
31	    private EpidemicCardService service;
32	
33	    @Test
34	    void concurrentReviewAndWithdraw_singleTerminalState() throws Exception {
35	        CardResponse card = service.submit(submitRequest("req-race-init", "P-RACE", "B02",
36	                BASE_TIME.minusSeconds(3600)));
37	
38	        ExecutorService pool = Executors.newFixedThreadPool(2);
39	        AtomicReference<CardStatus> winner = new AtomicReference<>();
40	        try {
41	            CyclicBarrier barrier = new CyclicBarrier(2);
42	            List<Future<?>> futures = new ArrayList<>();
43	
44	            futures.add(pool.submit(() -> {
45	                barrier.await(10, TimeUnit.SECONDS);
46	                service.review(card.cardNo(), new ReviewRequest("auditor-01", "并发初审"));
47	                winner.compareAndSet(null, CardStatus.PENDING_FINAL);
48	                return null;
49	            }));
50	            futures.add(pool.submit(() -> {
51	                barrier.await(10, TimeUnit.SECONDS);
52	                service.withdraw(card.cardNo(), new WithdrawRequest("reporter-1", "并发撤回"));
53	                winner.compareAndSet(null, CardStatus.WITHDRAWN);
54	                return null;
55	            }));
56	
57	            int success = 0;
58	            int rejected = 0;
59	            for (Future<?> future : futures) {
60	                try {
61	                    future.get(15, TimeUnit.SECONDS);
62	                    success++;
63	                } catch (Exception e) {
64	                    assertTrue(e.getCause() instanceof ApiException,
65	                            "落败动作须为业务异常，实际: " + e.getCause());
66	                    rejected++;
67	                }
68	            }
69	
70	            assertEquals(1, success, "初审与撤回并发只能有一个动作成功");
71	            assertEquals(1, rejected, "另一个动作必须被拒绝");
72	            assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM card", Integer.class));
73	
74	            CardStatus finalState = service.getCard(card.cardNo()).status();
75	            assertEquals(winner.get(), finalState, "数据库终态必须与胜出动作一致");
76	            assertTrue(finalState == CardStatus.PENDING_FINAL
77	                            || finalState == CardStatus.WITHDRAWN,
78	                    "终态只能是待终审或已撤回");
79	        } finally {
80	            pool.shutdownNow();
81	        }
82	    }
83	
84	    @Test
85	    void concurrentDuplicateSubmissions_onlyOneCardCreated() throws Exception {
86	        ExecutorService pool = Executors.newFixedThreadPool(2);
87	        try {
88	            CyclicBarrier barrier = new CyclicBarrier(2);
89	            List<Future<CardResponse>> futures = new ArrayList<>();
90	            for (int i = 0; i < 2; i++) {
91	                int idx = i;
92	                futures.add(pool.submit(() -> {
93	                    SubmitCardRequest req = submitRequest("req-dup-conc-" + idx, "P-DUP-CONC",
94	                            "B02", BASE_TIME.minusSeconds(1800));
95	                    barrier.await(10, TimeUnit.SECONDS);
96	                    return service.submit(req);
97	                }));
98	            }
99	
100	            CardResponse r1 = futures.get(0).get(15, TimeUnit.SECONDS);
101	            CardResponse r2 = futures.get(1).get(15, TimeUnit.SECONDS);
102	            assertEquals(r1.cardNo(), r2.cardNo(), "并发重复报告必须指向同一张卡");
103	            assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM card", Integer.class),
104	                    "唯一约束须保证只有一张有效卡");
105	            assertEquals(1, jdbc.queryForObject(
106	                    "SELECT COUNT(*) FROM card_version WHERE card_no = ?", Integer.class,
107	                    r1.cardNo()));
108	        } finally {
109	            pool.shutdownNow();
110	        }
111	    }
112	}
