package com.example.starter.epidemic.domain;

/**
 * 聚集性疫情事件状态。
 *
 * <p>OPEN 进行中；CONFIRMED/EXCLUDED 为协查结论回写后的状态；CLOSED 为终态，
 * 关闭后重复关闭幂等成功，迟到的报告卡只记迟到事件、可另行归并成新事件。</p>
 */
public enum ClusterStatus {
    /** 进行中：事件生成后尚未回写协查结论。 */
    OPEN,
    /** 协查确认：协查结论为确认聚集。 */
    CONFIRMED,
    /** 协查排除：协查结论为排除聚集。 */
    EXCLUDED,
    /** 已关闭（终态）：不再接受正常归并，迟到卡只记迟到事件。 */
    CLOSED
}

package com.example.starter.epidemic.domain;

/**
 * 协查单状态：IN_PROGRESS 进行中；CONCLUDED 已办结（结论已回写聚集事件）。
 */
public enum InvestigationStatus {
    /** 进行中：同一聚集事件同一时刻仅允许一张。 */
    IN_PROGRESS,
    /** 已办结：结论已回写聚集事件状态（同一事务）。 */
    CONCLUDED
}

package com.example.starter.epidemic.domain;

/**
 * 报告卡归入聚集事件的归并类型。
 */
public enum ArrivalType {
    /** 窗口内正常归并：计入事件首末例与触发计数。 */
    NORMAL,
    /** 事件关闭后迟到：只记迟到事件，可另行归并成新事件。 */
    LATE
}

package com.example.starter.epidemic.domain;

/**
 * 合成暴露场所库行模型：报告卡现住址包含关键词即自动归并到该场所。
 */
public record ExposureSitePo(
        /** 场所编码。 */
        String code,
        /** 场所名称（合成）。 */
        String name,
        /** 地址归并关键词。 */
        String keyword) {
}

