package com.example.starter.epidemic.domain;

import java.time.Instant;

/**
 * 聚集性疫情事件行模型：同一场所 72 小时（UTC）内 3 例及以上报告触发。
 *
 * <p>{@code openInvestigationId} 为当前进行中协查单编号，由条件 UPDATE 保证
 * 同一事件同一时刻仅一张进行中协查单；CLOSED 为终态。</p>
 */
public class ClusterEventPo {
    /** 聚集事件编号，自增主键。 */
    private long id;
    /** 暴露场所编码。 */
    private String siteCode;
    /** 事件状态。 */
    private ClusterStatus status;
    /** 窗口内首例报告时刻（UTC）。 */
    private Instant firstCaseAt;
    /** 窗口内末例报告时刻（UTC）。 */
    private Instant lastCaseAt;
    /** 当前进行中协查单编号；无则为 null。 */
    private Long openInvestigationId;
    /** 协查结论回写内容；未回写为 null。 */
    private String conclusion;
    /** 事件生成时刻（UTC）。 */
    private Instant createdAt;
    /** 关闭时刻（UTC）；未关闭为 null。 */
    private Instant closedAt;

    public long getId() { return id; }
    public void setId(long id) { this.id = id; }
    public String getSiteCode() { return siteCode; }
    public void setSiteCode(String siteCode) { this.siteCode = siteCode; }
    public ClusterStatus getStatus() { return status; }
    public void setStatus(ClusterStatus status) { this.status = status; }
    public Instant getFirstCaseAt() { return firstCaseAt; }
    public void setFirstCaseAt(Instant firstCaseAt) { this.firstCaseAt = firstCaseAt; }
    public Instant getLastCaseAt() { return lastCaseAt; }
    public void setLastCaseAt(Instant lastCaseAt) { this.lastCaseAt = lastCaseAt; }
    public Long getOpenInvestigationId() { return openInvestigationId; }
    public void setOpenInvestigationId(Long openInvestigationId) { this.openInvestigationId = openInvestigationId; }
    public String getConclusion() { return conclusion; }
    public void setConclusion(String conclusion) { this.conclusion = conclusion; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public Instant getClosedAt() { return closedAt; }
    public void setClosedAt(Instant closedAt) { this.closedAt = closedAt; }
}

package com.example.starter.epidemic.domain;

import java.time.Instant;

/**
 * 聚集事件涉及卡号行模型：记录卡号、报告时刻与归并类型（正常/迟到）。
 */
public record ClusterEventCardPo(
        /** 自增主键。 */
        long id,
        /** 聚集事件编号。 */
        long eventId,
        /** 卡片编号。 */
        String cardNo,
        /** 报告时刻（UTC）。 */
        Instant reportedAt,
        /** 归并类型：NORMAL 窗口内正常归并 / LATE 事件关闭后迟到。 */
        ArrivalType arrival) {
}

package com.example.starter.epidemic.domain;

import java.time.Instant;

/**
 * 协查单行模型：聚集事件生成后推送相关机构；requestId 唯一保证幂等。
 */
public class InvestigationPo {
    /** 协查单编号，自增主键。 */
    private long id;
    /** 聚集事件编号。 */
    private long eventId;
    /** 幂等键。 */
    private String requestId;
    /** 协查推送机构编码。 */
    private String institutionCode;
    /** 协查说明；无则为 null。 */
    private String note;
    /** 协查单状态。 */
    private InvestigationStatus status;
    /** 协查结论；未办结为 null。 */
    private String conclusion;
    /** 创建时刻（UTC）。 */
    private Instant createdAt;
    /** 办结时刻（UTC）；未办结为 null。 */
    private Instant concludedAt;

    public long getId() { return id; }
    public void setId(long id) { this.id = id; }
    public long getEventId() { return eventId; }
    public void setEventId(long eventId) { this.eventId = eventId; }
    public String getRequestId() { return requestId; }
    public void setRequestId(String requestId) { this.requestId = requestId; }
    public String getInstitutionCode() { return institutionCode; }
    public void setInstitutionCode(String institutionCode) { this.institutionCode = institutionCode; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public InvestigationStatus getStatus() { return status; }
    public void setStatus(InvestigationStatus status) { this.status = status; }
    public String getConclusion() { return conclusion; }
    public void setConclusion(String conclusion) { this.conclusion = conclusion; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public Instant getConcludedAt() { return concludedAt; }
    public void setConcludedAt(Instant concludedAt) { this.concludedAt = concludedAt; }
}

