            // 迟到卡登记到最新已关闭事件（只记迟到事件）
            var closed = clusterRepository.findLatestClosedEvent(site.code());
            if (closed.isPresent() && withinWindow(closed.get().getFirstCaseAt(), reportedAt)) {
